package com.tihai.controller;
import com.tihai.common.R;import com.tihai.utils.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Autowired;import org.jsoup.Jsoup;import java.util.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;
@RestController @RequestMapping("/local/exams") public class ExamController {
 @Autowired private SecurityAlertHub security;@Autowired private CourseExamCatalog catalog;@Autowired private Query query;@Autowired private LearningTongAiClient ai;@Autowired private LiveProgressTracker progress;@Autowired private QuizVisionService vision;@Autowired private ExamStateStore store;
 private final Map<String,Job> jobs=new ConcurrentHashMap<>();private final ExecutorService executor=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"exam-answer-worker");t.setDaemon(true);return t;});
 protected static class Job {final String id;final CourseExamCatalog.Entry entry;final boolean auto;volatile String state="queued",message="考试任务已排队",securityMessage="",securityEventId="";volatile int done,total;volatile boolean submitRequested,submissionClaimed;volatile Future<?> future;volatile ExamBrowserSession browser;final List<Map<String,Object>> questions=new CopyOnWriteArrayList<>();Job(String id,CourseExamCatalog.Entry e,boolean auto){this.id=id;entry=e;this.auto=auto;}}
 protected ExamBrowserSession openBrowser(String id)throws IOException{return new ExamBrowserSession.ProcessSession(Paths.get("D:/tool/qita/SuperAutoStudy"),id);}
 private Map<String,Object> state(Job j,boolean questions){Map<String,Object> m=new LinkedHashMap<>();m.put("state",j.state);m.put("message",j.message);m.put("done",j.done);m.put("total",j.total);m.put("autoSubmit",j.auto);m.put("submissionClaimed",j.submissionClaimed);m.put("securityEventId",j.securityEventId);m.put("securityMessage",j.securityMessage);if(questions)m.put("questions",new ArrayList<>(j.questions));return m;}
 private void persist(Job j)throws IOException{Map<String,Object> row=state(j,true);row.put("title",j.entry.title);row.put("course",j.entry.courseTitle);row.put("updatedAt",java.time.LocalDateTime.now().toString());store.save(j.id,row);}
 private boolean finished(String status){return Arrays.asList("已完成","待批阅","已交卷","已提交").contains(status);}
 @GetMapping("/list") public R list(){Map<String,Object> data=catalog.list();List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> original:(List<Map<String,Object>>)data.get("items")){Map<String,Object> row=new LinkedHashMap<>(original);String id=String.valueOf(row.get("id"));Job j=jobs.get(id);try{Map<String,Object> saved=j==null?store.load(id):state(j,false);if(saved!=null){saved=new LinkedHashMap<>(saved);saved.remove("questions");if(j==null&&!Arrays.asList("completed","failed","stopped","uncertain").contains(saved.get("state"))){saved.put("state",ExamStateStore.mayHaveSubmitted(saved)?"uncertain":"interrupted");saved.put("message","后台已重启，请先核对平台计时与作答状态；不会自动重交");}if(finished(String.valueOf(row.get("status")))&&ExamStateStore.mayHaveSubmitted(saved)){saved.put("state","completed");saved.put("message","平台列表确认已交卷");}row.put("job",saved);}}catch(Exception e){row.put("actionable",false);row.put("detail","本机考试记录无法读取，已禁用自动操作以保留原记录");}out.add(row);}Map<String,Object> result=new LinkedHashMap<>(data);result.put("items",out);return R.ok().setData(result);}
 @GetMapping("/alerts") public R alerts(){List<Map<String,Object>> items=new ArrayList<>();for(Job j:jobs.values())if(AccountScope.allows(j.entry.account)&&!j.securityEventId.isEmpty()&&"verification".equals(j.state)){Map<String,Object> a=new LinkedHashMap<>();a.put("eventId",j.securityEventId);a.put("title",j.entry.title);a.put("message",j.securityMessage);items.add(a);}return R.ok().setData(items);}
 @PostMapping("/notes") public R notes(@RequestBody Map<String,String> body){try{CourseExamCatalog.Entry e=catalog.entry(body.get("id"));String html=CourseExamCatalog.get(catalog.session(e.account).initSession(false,false),e.notesUrl);org.jsoup.nodes.Document d=Jsoup.parse(html);Map<String,Object> data=new LinkedHashMap<>();data.put("text",d.select(".examDescription,.examInfo,.exam-info,#examDescription,.exam-read,.readPad,table").text());if(String.valueOf(data.get("text")).isEmpty())data.put("text","考试："+e.title+"\n"+e.detail+"\n开始考试后平台计时持续进行；需要安全验证时在考试窗口完成。");return R.ok().setData(data);}catch(Exception e){return R.error(400,"考试须知读取失败，请刷新或重新登录");}}
 @PostMapping("/start") public synchronized R start(@RequestBody Map<String,Object> body){String id=String.valueOf(body.get("id"));try{CourseExamCatalog.Entry e=catalog.entry(id);if(!Boolean.TRUE.equals(body.get("confirmed")))return R.error(400,"需要确认进入考试；进入后将开始平台计时");if(!e.actionable)return R.error(409,"平台未提供可作答状态，未开始考试");Job old=jobs.get(id);if(old!=null&&!Arrays.asList("failed","stopped").contains(old.state))return R.error(409,"已有考试执行记录，请先查看；不会重复交卷");Map<String,Object> saved=store.load(id);if(ExamStateStore.mayHaveSubmitted(saved))return R.error(409,"该考试已有交卷记录或结果待确认，请先核对平台，不会重复发送");Job j=new Job(id,e,Boolean.TRUE.equals(body.get("autoSubmit")));persist(j);jobs.put(id,j);j.future=executor.submit(()->run(j));return R.ok("考试自动答题已排队；将打开平台考试窗口，遇到安全验证需人工完成");}catch(Exception ex){return R.error(400,"考试入口或本机记录不可用，未开始考试");}}
 private Map<String,Object> event(Job j,String wanted)throws Exception{while(true){progress.checkCancelled();Map<String,Object> event=j.browser.read();String kind=String.valueOf(event.get("event"));if("verification".equals(kind)){j.state="verification";j.securityMessage=String.valueOf(event.get("message"));j.securityEventId=UUID.randomUUID().toString();if(security!=null)security.raise("exams",j.id,j.entry.title,j.securityMessage);j.message=j.securityMessage;persist(j);continue;}if("error".equals(kind))throw new IOException(String.valueOf(event.get("message")));if("uncertain".equals(kind)){j.state="uncertain";j.message=String.valueOf(event.get("message"));persist(j);return event;}if("completed".equals(kind)){j.state="completed";j.message=String.valueOf(event.get("message"));persist(j);catalog.invalidate();return event;}if("submit_sent".equals(kind)){j.submissionClaimed=true;persist(j);continue;}if(wanted.equals(kind)){if("paper".equals(kind)){j.securityEventId="";j.securityMessage="";if(security!=null)security.resolve("exams",j.id);}return event;}throw new IOException("考试桥接返回的阶段不匹配");}}
 protected Map<String,Object> init(Job j)throws IOException{Map<String,Object> c=new LinkedHashMap<>();c.put("op","init");c.put("url",j.entry.notesUrl);c.put("courseId",j.entry.courseId);c.put("classId",j.entry.clazzId);c.put("examId",j.entry.examId);String pf=System.getenv("ProgramFiles(x86)");c.put("edge",Paths.get(pf==null?"C:/Program Files (x86)":pf,"Microsoft/Edge/Application/msedge.exe").toString());List<Map<String,String>> cookies=new ArrayList<>();for(Map.Entry<String,String> e:CourseUtil.convertCookieStringToMap(catalog.cookies(j.entry.account)).entrySet()){Map<String,String> cookie=new LinkedHashMap<>();cookie.put("name",e.getKey());cookie.put("value",e.getValue());cookie.put("domain",".chaoxing.com");cookie.put("path","/");cookies.add(cookie);}c.put("cookies",cookies);return c;}
 private void run(Job j){String old=ai==null?null:ai.bindAccount(j.entry.account);progress.begin("exam:"+j.id);try{j.state="starting";j.message="正在进入平台考试；进入后会开始计时";persist(j);j.browser=openBrowser(j.id);j.browser.send(init(j));Map<String,Object> event=event(j,"paper");Set<String> visited=new HashSet<>();while(!"completed".equals(j.state)&&!"uncertain".equals(j.state)){
  j.state="generating";String html=String.valueOf(event.get("html"));ExamPageParser.identity(html,j.entry.courseId,j.entry.clazzId,j.entry.examId);int count=ExamPageParser.total(html);if(j.total!=0&&j.total!=count)throw new IOException("考试总题数变化，未自动交卷");j.total=count;List<Map<String,Object>> questions=ExamPageParser.questions(html);if(questions.size()!=1)throw new IOException("本次试卷展示方式尚未验证，未自动交卷");Map<String,Object> q=questions.get(0);if(!visited.add(String.valueOf(q.get("id")))||ExamPageParser.index(html)!=j.done)throw new IOException("考试题序不连续，未自动交卷");if(!Arrays.asList("single","multiple","judgement").contains(q.get("type")))throw new IOException("考试自动填写当前支持单选、多选和判断题");Map<String,Object> page=new LinkedHashMap<>();page.put("questions",questions);vision.fill(html,page);progress.quiz(j.entry.title,j.total);progress.question(j.done+1,String.valueOf(q.get("type")));j.message="正在处理第 "+(j.done+1)+" / "+j.total+" 题";persist(j);String answer=AssignmentDraft.answer(query,q);q.put("answer",answer);Map<String,Object> live=progress.snapshot("exam:"+j.id);q.put("answerSource",live==null?"题库 / AI参考答案":live.get("answer_source"));Map<String,Object> apply=new LinkedHashMap<>();apply.put("op","apply");apply.put("id",q.get("id"));apply.put("type",q.get("type"));apply.put("answer",answer);j.browser.send(apply);event(j,"applied");j.questions.add(new LinkedHashMap<>(q));j.done++;progress.prepared(j.done);persist(j);if(j.done==j.total)break;j.browser.send(Collections.singletonMap("op","next"));event=event(j,"paper");}
  if("completed".equals(j.state)||"uncertain".equals(j.state))return;j.state="ready";j.message="全部答案已填写，尚未交卷；平台可能已暂存前面的题目";persist(j);while(!j.auto&&!j.submitRequested){Thread.sleep(200);progress.checkCancelled();}
  progress.checkCancelled();if(j.done!=j.total||j.total<=0)throw new IOException("考试未完整作答，未交卷");j.state="submitting";j.message="正在核对整卷并交卷，请勿重复操作";j.submissionClaimed=true;persist(j);Map<String,Object> submit=new LinkedHashMap<>();submit.put("op","submit");submit.put("total",j.total);j.browser.send(submit);event(j,"completed");
 }catch(Exception ex){if("stopped".equals(j.state)||ex instanceof CancellationException||Thread.currentThread().isInterrupted()){j.state="stopped";j.message="已停止自动答题；平台计时可能仍在继续，请自行核对考试";}else{j.state=j.submissionClaimed?"uncertain":"failed";j.message=ex instanceof IOException?ex.getMessage():"考试处理失败，未自动重复交卷";}try{persist(j);}catch(Exception ignored){}}
 finally{if(security!=null)security.resolve("exams",j.id);if(j.browser!=null)j.browser.close();if(ai!=null)ai.restoreAccount(old);progress.release();Thread.interrupted();}}
 @PostMapping("/draft") public R draft(@RequestBody Map<String,String> body){try{Job j=jobs.get(body.get("id"));Map<String,Object> data=j==null?store.load(body.get("id")):state(j,true);return data==null?R.error(404,"尚无本机考试作答记录"):R.ok().setData(data);}catch(Exception e){return R.error(400,"考试记录读取失败");}}
 @PostMapping("/submit") public synchronized R submit(@RequestBody Map<String,Object> body){Job j=jobs.get(String.valueOf(body.get("id")));if(j==null||!"ready".equals(j.state)||!Boolean.TRUE.equals(body.get("confirmed")))return R.error(409,"需要就绪的考试草稿及明确交卷确认");j.submitRequested=true;j.state="submitting";return R.ok("已请求核验整卷并交卷，请勿重复操作");}
 @PostMapping("/stop") public synchronized R stop(@RequestBody Map<String,String> body){Job j=jobs.get(body.get("id"));if(j==null||Arrays.asList("submitting","completed","uncertain").contains(j.state))return R.error(409,"没有可停止的自动答题；已发出的交卷不能撤回");j.state="stopped";j.message="已停止自动操作；考试计时可能仍在继续";progress.cancel("exam:"+j.id);if(j.browser!=null)j.browser.close();if(j.future!=null)j.future.cancel(true);try{persist(j);}catch(Exception ignored){}return R.ok(j.message);}
 @javax.annotation.PreDestroy public void shutdown(){for(Job j:jobs.values()){if(j.browser!=null)j.browser.close();}executor.shutdownNow();try{executor.awaitTermination(5,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}

